```java
public class Swap {
    static void swap(int[] a) { int t = a[0]; a[0] = a[1]; a[1] = t; }
    static void swapNew(int[] a) { a = new int[]{9, 9}; }

    public static void main(String[] args) {
        int[] p = {1, 2};
        swap(p);
        swapNew(p);
        System.out.println(p[0] + "," + p[1]);
    }
}
