```java
public class Scope {
    static int x = 1;

    static void f() {
        int x = 2;
        x++;
        System.out.print(x + " ");
    }

    public static void main(String[] args) {
        f();
        System.out.print(x + " ");
        for (int i = 0; i < 2; i++) {
            int y = i * 10;
            x += y;
        }
        System.out.println(x);
    }
}
```
